import './style.css';
import './load-style.js';
import * as db from './repository.js';
import { orderCommission, countedCommission, commissionPreview } from './commission.js';
import { encodeBackup, decodeBackup } from './backup.js';

const root = document.getElementById('app');
function routeFromHash(){const raw=decodeURIComponent(location.hash.slice(1)||'home');return /^(home|orders|customers|commission|reports|coaches|settings|settlements|profile|stores|order:[^:]+|customer:[^:]+)$/.test(raw)?raw:'home';}
const greeting = () => {const hour=new Date().getHours();return hour<6?'夜深了':hour<12?'早上好':hour<18?'下午好':'晚上好'};
const names = {home:'首页',orders:'订单',customers:'客户',commission:'提成',reports:'报表',coaches:'招生官'};
import { icons } from './icons.js';
const state = {view:routeFromHash(), data:{}, search:'', month:todayMonth(), monthInitialized:false, commissionFilterOpen:false, commissionFilters:{store:'all',owner:'all',course:'all',status:'all'}, customerFilterOpen:false, customerFilters:{tag:'all',store:'all',owner:'all'}, filterOpen:false, filters:{status:'all',settled:'all',course:'all',store:'all',owner:'all'}, sort:'time', coachFilter:'all', settlementFilter:'all', courseAdd:false, batchMode:false, selected:[], modal:null, error:'', toast:'', busy:false};
const h = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => '¥ ' + Math.round(Number(v)||0).toLocaleString('zh-CN');
function todayMonth(){return new Date().toLocaleDateString('sv-SE').slice(0,7)}
const defaults = { mode:'custom', fixedRate:15, countDue:true };
const settings = () => state.data.settings?.[0] || defaults;
const all = kind => state.data[kind] || [];
const byId = (kind,id) => all(kind).find(x => x.id === id);
const today = () => new Date().toLocaleDateString('sv-SE');
const nowStr = () => {const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;};
const sum = (items, fn) => items.reduce((a,x)=>a+fn(x),0);
const earned = o => countedCommission(o,settings(),all('course'));
const grossCount = o => settings().countDue===false && o.status==='due' ? 0 : orderCommission(o,settings(),all('course')).gross;
const chartCommission = o => orderCommission(o,settings(),all('course')).earned;
const empty = (msg) => `<div class="empty">${icons.empty}<div>${h(msg)}</div></div>`;
const tag = (text, color='') => `<span class="tag ${color}">${h(text)}</span>`;
const btn = (label,action,klass='') => `<button class="${klass}" data-action="${h(action)}">${h(label)}</button>`;
const hints={name:'请输入姓名',phone:'请输入联系电话',enrollDate:'如 2026-08-14 或 8月初',examDate:'如 2026-09-01 或 待定',store:'可直接填写，如 总店 / 分校',owner:'如 王教练（也可填写外部推荐人）',classTime:'如 月初 / 周末场 / 工作日晚上',payMethod:'如 微信 / 现金 / 对公转账',recruiter:'如 王教练',examiner:'如 李老师',followUp:'如 张顾问',fee:'如 3500',discount:'0',depositDate:'如 2026-08-14 或 待定',balanceDate:'如 2026-09-01 或 待定',secondCommission:'如 200，没有可留空',secondReferrer:'如 老客户王女士',examTime:'如 2026-09-15 上午',examPlace:'如 宝山考点 / 总校机房',classPlace:'如 总店 2 号教室'};
const field = (label,name,value='',type='text',placeholder='') => `<div class="field"><label for="f-${h(name)}">${h(label)}</label><input id="f-${h(name)}" name="${h(name)}" type="${h(type)}" value="${h(value)}" placeholder="${h(placeholder||hints[name]||'')}"></div>`;
function header(title,back='home',extra='') { return `<header class="header">${back?btn('‹',`go:${back}`,'back'):''}<h1>${h(title)}</h1>${extra}</header>`; }
function card(title,sub,right,action,initial) { return `<div class="list-card" data-action="${h(action)}"><div class="avatar">${h((initial || title || '未')[0])}</div><div class="item-main"><strong>${h(title)}</strong><small>${h(sub)}</small></div><div class="item-right">${right}</div></div>`; }
function orderCard(o) { if(state.batchMode&&state.view==='orders')return `<div class="list-card" data-action="select-order:${h(o.id)}"><span class="tag">${state.selected.includes(o.id)?'✓':'○'}</span><div class="item-main"><strong>${h(o.name)}</strong><small>${h(o.course||'')} · ${h(o.owner||'未分配')}</small></div><div class="item-right">${money(o.fee)}</div></div>`;return `<div class="list-card ${o.settled?'':'order-pending'}" data-action="order:${h(o.id)}"><div class="avatar">${h((o.name||'未')[0])}</div><div class="item-main"><strong>${h(o.name)}</strong><small><span class="course-link" data-action="quick-course:${h(o.id)}">${h(o.courseLabel||o.course||'')}</span> · ${h(o.owner||'未分配')}${o.store?' · '+h(o.store):''}</small></div><div class="item-right">${money(o.fee)}<small>${h(o.time||'')}</small>${tag(o.status==='due'?'待付款':'已结清',o.status==='due'?'orange':'green')} ${tag(o.settled?'已结算':'待结算',o.settled?'green':'orange')}</div></div>`; }
function customerCard(c) { return card(c.name,[c.phone,c.course,c.owner,c.store].filter(Boolean).join(' · '),(c.tags||[]).map(t=>tag(t)).join(''),`customer:${c.id}`); }
function groupCoaches(orders=all('order')) {
 const map = new Map();
 for(const o of orders) {const key=o.owner||'未分配'; if(!map.has(key)) map.set(key,{name:key,orders:[],earned:0,settled:0}); const x=map.get(key);x.orders.push(o);x.earned+=earned(o); if(o.settled)x.settled+=earned(o);}
 return [...map.values()];
}
function nav() { return `<nav class="tabs">${Object.keys(names).map(k=>`<button data-action="go:${k}" class="${state.view===k?'active':''}"><span>${icons[k]}</span>${names[k]}</button>`).join('')}</nav>`; }
function sparkBars(vals){const max=Math.max(...vals,1),height=40,bw=8,gap=6,x0=Math.max(0,(132-(vals.length*bw+(vals.length-1)*gap))/2);return `<svg width="100%" height="40" viewBox="0 0 132 40" preserveAspectRatio="none">${vals.map((v,i)=>{const bh=Math.max(3,Math.round(v/max*height));return `<rect x="${x0+i*(bw+gap)}" y="${height-bh}" width="${bw}" height="${bh}" rx="2.5" fill="#A68CFA"/>`}).join('')}</svg>`;}
function sparkLine(vals){const max=Math.max(...vals,1),height=40,width=132,pad=4,pts=vals.map((v,i)=>[pad+i*(width-pad*2)/Math.max(vals.length-1,1),height-pad-v/max*(height-pad*2)]),line=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' '),area=`M${pts[0][0].toFixed(1)} ${height} `+line.slice(1)+` L${pts.at(-1)[0].toFixed(1)} ${height} Z`;return `<svg width="100%" height="40" viewBox="0 0 132 40" preserveAspectRatio="none"><path d="${area}" fill="#7D3BED" opacity="0.12"/><path d="${line}" fill="none" stroke="#7D3BED" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function home() {
 const orders=all('order'),pending=orders.filter(o=>!o.settled),t=today(),total=sum(orders,grossCount),todays=orders.filter(o=>o.time===t);
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d.toLocaleDateString('sv-SE')});
 const counts=days.map(day=>orders.filter(o=>o.time===day).length),amounts=days.map(day=>sum(orders.filter(o=>o.time===day),grossCount));
 const pendingByCoach=new Map();for(const o of pending){const name=o.owner||'未分配';pendingByCoach.set(name,(pendingByCoach.get(name)||0)+grossCount(o))}const pendingLine=[...pendingByCoach].sort((a,b)=>b[1]-a[1]).slice(0,2).map(([name,n])=>h(name)+' '+money(n)).join(' · ')+(pendingByCoach.size>2?' 等':'');
 const d=new Date(),dateText=`${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日 星期${'日一二三四五六'[d.getDay()]}`;
 return `<header class="header home-head"><div class="home-title"><h1>${greeting()}，管理员</h1><small>${h(dateText)}</small></div><button class="icon theme-icon" data-action="theme" title="切换深浅色"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg></button>${btn('管','go:profile','profile-button')}</header><div class="body"><div class="hero"><small>本月实际提成</small><strong>${money(total)}</strong><div class="metrics"><div>今日订单<b>${todays.length}</b></div><div>今日营收<b>${money(sum(todays,o=>(+o.fee||0)-(+o.discount||0)))}</b></div><div>新增客户<b>${all('customer').filter(x=>(x.join||'').startsWith(t.slice(0,7))).length}</b></div></div></div><div class="warn home-warn ${pending.length?'':'done'}" data-action="home-unsettled"><span class="warn-icon">${pending.length?'⏳':'✓'}</span><span><b>${pending.length?'还有 '+pending.length+' 笔佣金待结算':'全部佣金已结算'}</b><small>${pending.length?'待结算合计 '+money(sum(pending,grossCount)):'当前没有待结算的提成'}</small>${pendingLine?`<small class="warn-coaches">待付：${pendingLine}</small>`:''}</span><b class="warn-go">${pending.length?'去处理 →':'查看'}</b></div><div class="quick home-quick">${[[icons.add,'新增订单','new:order'],[icons.settings,'提成设置','go:settings'],[icons.reports,'结算明细','go:settlements'],[icons.coaches,'招生官业绩','go:coaches'],[icons.store,'门店管理','go:stores']].map(([i,t,a])=>`<button data-action="${a}"><b>${i}</b>${t}</button>`).join('')}</div><div class="trend-card"><div class="trend-head"><h2>数据看板</h2><small>近 7 日</small></div><div class="trend-grid"><div class="trend-item"><small>新增订单</small><strong>${sum(counts,x=>x)}</strong>${sparkBars(counts)}</div><div class="trend-item"><small>提成</small><strong class="purple">${money(sum(amounts,x=>x))}</strong>${sparkLine(amounts)}</div></div></div><div class="section"><h2>招生官业绩排行</h2>${btn('查看全部','go:coaches','link')}</div>${groupCoaches().sort((a,b)=>b.earned-a.earned).slice(0,3).map((x,i)=>{const color=['#F6B93B','#9AA5B1','#D58B5A'][i];return `<div class="rank-card" data-action="coach-name:${h(encodeURIComponent(x.name))}"><span class="rank-medal"><svg width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="${color}" opacity="0.15"/><circle cx="12" cy="12" r="10" fill="none" stroke="${color}" stroke-width="1.6"/><text x="12" y="16" text-anchor="middle" font-size="11" font-weight="700" fill="${color}">${i+1}</text></svg></span><span class="rank-name">${h(x.name)}</span><span class="rank-sub">${x.orders.length} 单 · 已结算 ${x.earned?Math.round(x.settled/x.earned*100):0}%</span><span class="rank-amt">${money(x.earned)}</span></div>`}).join('') || empty("暂无业绩")}<div class="section"><h2>最近订单</h2>${btn('查看全部','go:orders','link')}</div>${orders.slice(0,3).map(orderCard).join('')||empty("暂无订单")}</div>`;
}
function listView(kind) {
 const isOrder=kind==='order', isCustomer=kind==='customer', title=isOrder?'订单管理':isCustomer?'客户管理':'门店管理';
 let items=all(kind).filter(x=>[x.name,x.phone,x.course,x.courseLabel,x.address,x.owner,x.store].some(v=>String(v||'').toLowerCase().includes(state.search.toLowerCase())));if(isOrder){const f=state.filters;items=items.filter(x=>(f.status==='all'||x.status===f.status)&&(f.settled==='all'||(f.settled==='settled'?x.settled:!x.settled))&&(f.course==='all'||x.course===f.course)&&(f.store==='all'||x.store===f.store)&&(f.owner==='all'||(f.owner==='__none__'?!x.owner:x.owner===f.owner)));items.sort((a,b)=>state.sort==='amount'?(b.fee||0)-(a.fee||0):state.sort==='commission'?chartCommission(b)-chartCommission(a):state.sort==='settled'?Number(!!a.settled)-Number(!!b.settled):String(b.time||'').localeCompare(String(a.time||'')));}else if(isCustomer){const f=state.customerFilters;items=items.filter(x=>(f.tag==='all'||(x.tags||[]).includes(f.tag))&&(f.store==='all'||x.store===f.store)&&(f.owner==='all'||(f.owner==='__none__'?!x.owner:x.owner===f.owner)));}
 const stats=isOrder?'':`<div class="stats"><div class="stat"><strong>${all(kind).length}</strong><small>${isCustomer?'总客户':'门店总数'}</small></div><div class="stat"><strong>${isCustomer?all(kind).filter(x=>x.join?.startsWith(today().slice(0,7))).length:all(kind).filter(x=>x.status==='营业').length}</strong><small>${isCustomer?'本月新增':'营业中'}</small></div></div>`;
 return `${header(title,kind==='store'?'home':'',(isOrder?btn('☷','toggle-filter','icon')+btn('☑','toggle-batch','icon'):isCustomer?btn('☷','customer-filter','icon'):'')+btn('＋',`new:${kind}`,'icon'))}<div class="body">${stats}${isOrder?orderTools():isCustomer?customerTools():''}<input class="search" id="search" placeholder="${isOrder?'搜索姓名、电话、课程':isCustomer?'搜索客户姓名、电话':'搜索门店名称、地址'}" value="${h(state.search)}">${isOrder&&all('order').some(o=>!o.settled)?`<div class="warn order-quick-settle"><span>待结算 ${all('order').filter(o=>!o.settled).length} 笔 · ${money(sum(all('order').filter(o=>!o.settled),grossCount))}</span>${btn('一键结算','quick-settle','chip')}</div>`:''}${items.map(x=>isOrder?orderCard(x):isCustomer?customerCard(x):card(x.name,[x.address,x.phone].filter(Boolean).join(' · '),tag(x.status,x.status==='营业'?'green':'orange'),`edit:store:${x.id}`)).join('')||empty("暂无记录")}</div>`;
}
function monthSelector(){const label=state.month==='all'?'全部时间':state.month.replace('-','年')+'月';return `<button class="time-pill" data-action="open-month">${h(label)} ▾</button>`;}

function monthOrders(){return state.month==='all'?all('order'):all('order').filter(o=>(o.time||'').startsWith(state.month));}
function filterChips(label,key,values,selected,action){return `<div class="filter-group"><small>${h(label)}</small><div class="chips">${values.map(([v,t])=>`<button class="chip ${selected===v?'active':''}" data-action="${action}:${h(key)}:${h(encodeURIComponent(v))}">${h(t)}</button>`).join('')}</div></div>`;}
function customerTools(){if(!state.customerFilterOpen)return '';const f=state.customerFilters;const options=(label,key,values)=>filterChips(label,key,values,f[key],'set-customer-filter');return `<div class="card">${options('按标签','tag',[['all','全部'],...['VIP','活跃','待付款','新客'].map(x=>[x,x])])}${options('按门店','store',[['all','全部'],...all('store').map(x=>[x.name,x.name])])}${options('按招生官','owner',[['all','全部'],['__none__','未分配'],...all('coach').map(x=>[x.name,x.name])])}${btn('重置筛选','reset-customer','primary secondary')}</div>`;}
function orderTools(){const f=state.filters;const option=(label,name,values)=>filterChips(label,name,values,f[name],'set-order-filter');return `${state.batchMode?`<div class="card">已选 ${state.selected.length} 项<div class="bar">${btn('批量结算','batch:settle','primary')}${btn('批量删除','batch:delete','primary danger')}${btn('退出','toggle-batch','primary secondary')}</div></div>`:''}${state.filterOpen?`<div class="card">${option('按状态','status',[['all','全部'],['paid','已结清'],['due','待付款']])}${option('按结算','settled',[['all','全部'],['unsettled','待结算'],['settled','已结算']])}${option('按课程','course',[['all','全部'],...all('course').map(c=>[c.name,c.name])])}${option('按门店','store',[['all','全部'],...all('store').map(c=>[c.name,c.name])])}${option('按招生官','owner',[['all','全部'],['__none__','未分配'],...all('coach').map(c=>[c.name,c.name])])}<div class="field"><label>排序方式</label><select id="order-sort"><option value="time">按时间最新</option><option value="amount" ${state.sort==='amount'?'selected':''}>按金额最高</option><option value="commission" ${state.sort==='commission'?'selected':''}>按提成最高</option><option value="settled" ${state.sort==='settled'?'selected':''}>待结算优先</option></select></div>${btn('重置筛选','reset-filters','primary secondary')}</div>`:''}`;}
function commissionTools(){if(!state.commissionFilterOpen)return '';const f=state.commissionFilters;const options=(label,key,values)=>filterChips(label,key,values,f[key],'set-commission-filter');return `<div class="card">${options('按门店','store',[['all','全部'],...all('store').map(x=>[x.name,x.name])])}${options('按招生官','owner',[['all','全部'],['__none__','未分配'],...all('coach').map(x=>[x.name,x.name])])}${options('按课程','course',[['all','全部'],...all('course').map(x=>[x.name,x.name])])}${options('按状态','status',[['all','全部'],['paid','已结清'],['due','待付款']])}${btn('重置筛选','reset-commission','primary secondary')}</div>`;}
function commissionOrders(){const f=state.commissionFilters;return monthOrders().filter(o=>(f.store==='all'||o.store===f.store)&&(f.owner==='all'||(f.owner==='__none__'?!o.owner:o.owner===f.owner))&&(f.course==='all'||o.course===f.course)&&(f.status==='all'||o.status===f.status));}
function commission() {const orders=commissionOrders(),rateOrders=orders.filter(o=>o.commissionType!=='fixed'),avg=rateOrders.length?Math.round(sum(rateOrders,o=>orderCommission(o,settings(),all('course')).rate)/rateOrders.length):null;return `${header('提成计算','',btn('☷','commission-filter','icon')+monthSelector())}<div class="body">${commissionTools()}<div class="hero"><small>${state.month==='all'?'总提成（全部时间）':'本月总提成'}</small><strong>${money(sum(orders,earned))}</strong><div class="metrics"><div>提成订单<b>${orders.length}</b></div><div>平均费率<b>${settings().mode==='fixed'?settings().fixedRate+'%':avg==null?'—':avg+'%'}</b></div></div></div><div class="section"><h2>功能入口</h2></div><div class="quick">${[[icons.settings,'提成设置','go:settings'],[icons.reports,'结算明细','go:settlements'],[icons.download,'导出明细','export:commission']].map(([i,t,a])=>`<button data-action="${a}"><b>${i}</b>${t}</button>`).join('')}</div><div class="section"><h2>提成明细</h2></div>${orders.map(o=>`<div class="card" data-action="order:${h(o.id)}">${[['客户',o.name],['课程',o.courseLabel||o.course],['门店',o.store||'—'],['归属招生官',o.owner||'—'],['报名费用',money(o.fee)],['提成比例',o.commissionType==='fixed'?'固定':orderCommission(o,settings(),all('course')).rate+'%'],['结算',o.settled?'已结算':'待结算'],...(o.secondReferrer?[['二级来源',o.secondReferrer]]:[]),['实际提成',money(orderCommission(o,settings(),all('course')).earned)]].map(([k,v])=>`<div class="row"><span>${h(k)}</span><b>${h(v)}</b></div>`).join('')}</div>`).join('')||empty("暂无订单")}</div>`; }
function coaches() {const groups=groupCoaches();return `${header('招生官管理','',btn('↓','export:coach','icon')+btn('＋','new:coach','icon'))}<div class="body"><div class="stats"><div class="stat"><strong>${all('coach').length}</strong><small>招生官总数</small></div><div class="stat"><strong>${money(sum(groups,x=>x.earned))}</strong><small>提成总额</small></div></div><input class="search" id="search" placeholder="搜索招生官姓名" value="${h(state.search)}"><div class="chips">${[['all','全部'],['合作教练','合作教练'],['离职','离职']].map(([v,t])=>`<button class="chip ${state.coachFilter===v?'active':''}" data-action="coach-filter:${v}">${t}</button>`).join('')}</div>${groups.filter(x=>x.name.includes(state.search)&&(state.coachFilter==='all'||(all('coach').find(c=>c.name===x.name)?.status||'合作教练')===state.coachFilter)).map(x=>card(x.name,`客户 ${new Set(x.orders.map(o=>o.name+'|'+o.phone)).size} · 订单 ${x.orders.length}`,`${money(x.earned)}<small>已结算 ${x.earned?Math.round(x.settled/x.earned*100):0}%</small>`,`coach-name:${encodeURIComponent(x.name)}`)).join('')||empty("暂无业绩")}</div>`; }
function reports(){const selected=monthOrders();const groups=groupCoaches(selected).filter(x=>x.earned>0).sort((a,b)=>b.earned-a.earned);const groupMax=Math.max(1,...groups.map(x=>x.earned));const months=[...new Set(all('order').map(o=>(o.time||'').slice(0,7)).filter(Boolean))].sort();const totals=months.map(m=>sum(all('order').filter(o=>(o.time||'').startsWith(m)),chartCommission));const max=Math.max(1,...totals);return `${header('报表统计','',monthSelector())}<div class="body"><div class="section"><h2>提成趋势（按月）</h2></div><div class="card report-chart"><div class="report-heading"><div><b>月度提成</b><small>按订单实际结算汇总</small></div><strong>${money(sum(all('order'),chartCommission))}</strong></div><div class="chart">${totals.map((n,i)=>`<div class="chart-col"><b>${n>=1000?(n/1000).toFixed(1)+'k':n}</b><i style="height:${Math.max(3,n/max*100)}%"></i><small>${h(Number(months[i].slice(5))+'月')}</small></div>`).join('')||empty("暂无数据")}</div></div><div class="section"><h2>招生官业绩对比</h2></div><div class="card"><div class="report-heading"><div><b>各招生官提成</b><small>当前时段内按招生官汇总</small></div><small>🟣 已结算　🟠 待结算</small></div>${groups.map(x=>{const pending=Math.max(0,x.earned-x.settled),totalWidth=Math.max(8,Math.round(x.earned/groupMax*100)),width=x.earned?Math.round(x.settled/x.earned*totalWidth):0;return `<div class="coach-bar"><b>${h(x.name)}</b><div class="coach-track"><i style="width:${width}%"></i><em style="width:${totalWidth-width}%"></em></div><strong>${money(x.earned)}</strong><small><span>已结算 ${money(x.settled)}</span>　<em>待结算 ${money(pending)}</em></small></div>`}).join('')||empty("暂无数据")}</div><div class="stats"><div class="stat"><strong>${money(sum(selected,o=>(+o.fee||0)))}</strong><small>实际总费用</small></div><div class="stat"><strong>${money(sum(selected,earned))}</strong><small>总提成</small></div></div><div class="section"><h2>数据管理</h2></div><div class="card">${[['导出表格','导出报名学员信息跟进表','export:table'],['导出文档','生成可打印的报表','export:document'],['导入订单','从 CSV 文件批量导入订单','import:orders'],['下载导入模板','获取标准 CSV 填写格式','export:template'],['导出数据备份','下载全部数据 JSON 文件','backup:export'],['导入数据备份','从备份文件恢复全部数据','backup:import']].map(([t,sub,a])=>`<div class="data-row" data-action="${a}"><div class="data-icon">${icons.download}</div><div><b>${h(t)}</b><small>${h(sub)}</small></div><strong>›</strong></div>`).join('')}</div><small>导入格式：姓名,电话,课程,级别,费用,优惠,状态,时间,归属招生官,提成比例</small></div>`;}

function selectField(label,name,value,items) {return `<div class="field"><label>${h(label)}</label><select name="${h(name)}">${items.map(v=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(({rate:'按提成比例',fixed:name==='mode'?'固定比例':'按固定金额',custom:'自定义课程比例'})[v]||v||'未选择')}</option>`).join('')}</select></div>`;}
function chipField(label,name,value,items,labels={}) {return `<div class="field"><label>${h(label)}</label><input type="hidden" name="${h(name)}" value="${h(value)}"><div class="chips">${items.map(v=>`<button type="button" class="chip ${v===value?'active':''}" data-chip="${h(name)}" data-value="${h(v)}">${h(labels[v]||v)}</button>`).join('')}</div></div>`;}
function counterField(label,key,value,logs){return `<div class="field"><label>${h(label)}（可多次记录）</label><input type="hidden" name="${key}" value="${Number(value)||0}"><div class="counter"><button type="button" data-counter="${key}" data-delta="-1">−</button><b data-counter-value="${key}">${Number(value)||0}</b><button type="button" data-counter="${key}" data-delta="1">＋</button><small data-counter-last="${key}">${logs?.length?'最近：'+h(logs[logs.length-1]):''}</small></div></div>`;}
function formView(kind,id) {
 const o=byId(kind,id)||{}, editing=!!id, labels={order:'订单',customer:'客户',coach:'招生官',store:'门店',course:'课程'};
 const common = kind==='order' ? `${field('客户姓名','name',o.name)}${field('联系电话','phone',o.phone,'tel')}${field('报名时间（手动填写）','enrollDate',o.enrollDate)}${field('报考时间（手动填写）','examDate',o.examDate)}<div class="field"><label>课程类型（可直接输入）</label><input name="course" list="courses" value="${h(o.course||all('course')[0]?.name||'')}"><datalist id="courses">${all('course').map(c=>`<option value="${h(c.name)}">`).join('')}</datalist></div>${chipField('报考级别','level',o.level||'初级',['初级','中级','高级','无'],{'无':'无 / 不用级别'})}${field('培训门店','store',o.store)}${field('推荐者（可直接填写）','owner',o.owner)}${field('上课时间','classTime',o.classTime)}${field('支付方式','payMethod',o.payMethod)}${field('招生老师','recruiter',o.recruiter)}${field('考官','examiner',o.examiner)}${field('跟进人','followUp',o.followUp)}${field('报名总金额（元）','fee',o.fee??all('course')[0]?.price??0,'number')}${field('优惠价格（元）','discount',o.discount??0,'number')}${field('实到金额（元）','actualFee',o.actualFee??Math.max(0,(o.fee??all('course')[0]?.price??0)-(o.discount??0)),'number')}${chipField('提成计算方式','commissionType',o.commissionType||'rate',['rate','fixed'],{rate:'按提成比例',fixed:'按固定金额'})}<div class="rate-fields" ${o.commissionType==='fixed'?'hidden':''}><div class="field"><label>当前提成比例</label><input value="${h(o.customRate??all('course').find(c=>c.name===(o.course||all('course')[0]?.name))?.rate??0)}%" readonly></div><div class="field"><label><input type="checkbox" name="useCustomRate" ${o.customRate!=null?'checked':''}> 单独设置本单提成比例</label><input name="customRate" type="number" value="${h(o.customRate??all('course')[0]?.rate??0)}" ${o.customRate==null?'disabled':''}></div></div><div class="fixed-fields" ${o.commissionType==='fixed'?'':'hidden'}>${field('固定提成金额（元）','fixedAmount',o.fixedAmount??0,'number')}</div>${field('订金支付时间','depositDate',o.depositDate)}${field('尾款支付时间','balanceDate',o.balanceDate)}<div class="field"><label><input type="checkbox" name="settled" ${o.settled?'checked':''}> 已结算佣金</label></div>${field('二级分成金额（元）','secondCommission',o.secondCommission??0,'number')}${field('二级推荐人','secondReferrer',o.secondReferrer)}${field('考试时间','examTime',o.examTime)}${field('考试地点','examPlace',o.examPlace)}${field('上课地点','classPlace',o.classPlace)}${field('备注','remark',o.remark)}<div class="field"><label>跟进状态</label>${[['hasBook','已发教材'],['enrolled','报名确认'],['examinerConfirmed','考场确认']].map(([key,label])=>`<label><input type="checkbox" name="${key}" ${o[key]?'checked':''}> ${label}</label>`).join('')}</div>${counterField('已开刷题','practiceCount',o.practiceCount,o.practiceLog)}${counterField('已进群','joinedCount',o.joinedCount,o.joinedLog)}` : kind==='customer' ? `${field('客户姓名','name',o.name)}${field('联系电话','phone',o.phone,'tel')}<div class="field"><label>客户标签</label><div class="chips">${['VIP','活跃','待付款','新客'].map(t=>`<label class="chip"><input type="checkbox" name="tag" value="${h(t)}" ${(o.tags||['VIP']).includes(t)?'checked':''}> ${h(t)}</label>`).join('')}</div></div>${selectField('当前课程','course',o.course||all('course')[0]?.name||'',all('course').map(c=>c.name))}${selectField('所属门店','store',o.store||'', [''].concat(all('store').map(s=>s.name)))}${selectField('归属招生官 / 销售','owner',o.owner||'', [''].concat(all('coach').map(c=>c.name)))}` : kind==='coach' ? `${field('招生官姓名','name',o.name)}${field('联系电话','phone',o.phone,'tel')}${chipField('招生官类型','status',o.status||'合作教练',['合作教练','离职'])}${field('入职日期','join',o.join||today(),'date')}${field('开户银行','bankName',o.bankName)}${field('银行卡号','account',o.account)}${field('持卡人姓名','holder',o.holder)}${field('支付宝账号','alipay',o.alipay)}${field('微信号','wechat',o.wechat)}${field('身份证号码','idcard',o.idcard)}` : kind==='store' ? `${field('门店名称','name',o.name)}${field('门店地址','address',o.address)}${field('联系电话','phone',o.phone)}${chipField('门店状态','status',o.status||'营业',['营业','停业'])}` : `${field('课程名称','name',o.name)}${field('默认比例','rate',o.rate??0,'number')}${field('默认价格','price',o.price??0,'number')}`;
 return `${header((editing?'编辑':'新增')+labels[kind],kind==='order'?'orders':kind==='customer'?'customers':kind==='coach'?'coaches':kind==='store'?'stores':'settings')}<div class="body"><form id="edit-form" data-kind="${kind}" data-id="${h(id||'')}">${common}${kind==='order'?`<div class="card" id="preview">预计实际提成 ${money(commissionPreview({fee:o.fee??all('course')[0]?.price??0,discount:o.discount??0,rate:o.customRate??all('course')[0]?.rate??0,commissionType:o.commissionType||'rate',fixedAmount:o.fixedAmount??0}).amount)}</div>`:''}<div class="save-bar"><button class="primary" type="submit">保存${labels[kind]}</button></div></form></div>`;
}
function detailOrder(o){const c=orderCommission(o,settings(),all('course'));const editable=[['报名时间','enrollDate'],['报考时间','examDate'],['上课时间','classTime'],['培训门店','store'],['推荐者','recruiter'],['归属招生官','owner'],['报名总金额','fee'],['优惠价格','discount'],['订金支付时间','depositDate'],['尾款支付时间','balanceDate'],['考试时间','examTime'],['考试地点','examPlace'],['上课地点','classPlace']];return `${header('订单详情','orders',btn('⋮',`order-menu:${o.id}`,'icon'))}<div class="body"><div class="card order-person"><div class="avatar">${h(o.name?.[0]||'客')}</div><div><h2>${h(o.name)}</h2>${tag(o.status==='due'?'待付款':'已结清',o.status==='due'?'orange':'green')}</div></div><div class="card detail-info"><h3>订单信息</h3><div class="row"><span>课程类型</span><b class="course-link" data-action="quick-course:${h(o.id)}">${h(o.courseLabel||o.course)}</b></div><div class="field"><label>报考级别</label><div class="chips">${['初级','中级','高级','无'].map(level=>`<button class="chip ${o.level===level?'active':''}" data-action="order-level:${h(o.id)}:${h(level)}">${level==='无'?'无 / 不用级别':level}</button>`).join('')}</div></div>${editable.map(([label,key])=>`<div class="row"><span>${h(label)}</span><input class="inline-field" aria-label="${h(label)}" data-od-field="${key}" data-id="${h(o.id)}" value="${h(o[key]??'')}"></div>`).join('')}${[['下单时间',o.time],['联系电话',o.phone],['提成比例',o.commissionType==='fixed'?'固定金额':c.rate+'%'],['正价提成',o.commissionType==='fixed'?'固定':money(Math.round((+o.fee||0)*c.rate/100))],['分摊优惠提成',o.commissionType==='fixed'?'—':money(Math.round((+o.discount||0)*c.rate/100))],['主提成',money(c.gross)],['二级分成',money(o.secondCommission)],['实得提成',money(c.earned)],['提成方式',o.commissionType==='fixed'?'固定金额':'按比例'],['结算时间',o.settledAt||'—']].map(([a,b])=>`<div class="row"><span>${h(a)}</span><b>${h(b||'—')}</b></div>`).join('')}<div class="row"><span>结算状态</span>${btn(o.settled?'已结算':'待结算',`settle:${o.id}`,'chip')}</div></div><div class="card"><h3>二级推荐分成</h3><small>从主提成扣，不单独结算</small>${[['二级分成金额','secondCommission'],['二级推荐人','secondReferrer']].map(([label,key])=>`<div class="row"><span>${label}</span><input class="inline-field" aria-label="${label}" data-od-field="${key}" data-id="${h(o.id)}" value="${h(o[key]??'')}"></div>`).join('')}</div><div class="card"><h3>跟进记录</h3>${[['已发教材','hasBook'],['报名确认','enrolled'],['考场确认','examinerConfirmed']].map(([label,key])=>`<div class="row"><span>${label}</span>${btn(o[key]?'是':'否',`flag:${key}:${o.id}`,'chip')}</div>`).join('')}${[['已开刷题','practiceCount'],['已进群','joinedCount']].map(([label,key])=>`<div class="row"><span>${label}（可多次记录）<small>${(o[key==='practiceCount'?'practiceLog':'joinedLog']||[]).length?'最近：'+h((o[key==='practiceCount'?'practiceLog':'joinedLog']||[]).at(-1)):''}</small></span><span>${btn('−',`count:${key}:${o.id}:-1`,'chip')} ${Number(o[key])||0} ${btn('＋',`count:${key}:${o.id}:1`,'chip')}</span></div>`).join('')}</div><div class="detail-bar">${btn('编辑',`edit:order:${o.id}`,'primary secondary')}${btn('删除',`delete:order:${o.id}`,'primary danger')}</div></div>`;}

function detailCustomer(c){const orders=all('order').filter(o=>o.name===c.name&&o.phone===c.phone);return `${header('客户详情','customers')}<div class="body"><div class="card profile-card"><div class="avatar">${h(c.name[0])}</div><h2>${h(c.name)}</h2>${(c.tags||[]).map(t=>tag(t)).join('')}</div><div class="stats"><div class="stat"><strong>${money(c.spend||0)}</strong><small>累计消费</small></div><div class="stat"><strong>${h(c.orders||0)}</strong><small>订单数</small></div><div class="stat"><strong>${h((c.expire||'').slice(0,7)||'—')}</strong><small>到期</small></div></div><div class="card"><h3>客户信息</h3><div class="row"><span>联系电话</span><b>${h(c.phone||'—')}</b></div>${[['归属招生官','owner'],['所属门店','store'],['当前课程','course'],['加入时间','join']].map(([label,key])=>`<div class="row"><span>${label}</span><input class="inline-field" aria-label="${label}" data-cd-field="${key}" data-id="${h(c.id)}" value="${h(c[key]??'')}"></div>`).join('')}</div><div class="section"><h2>关联订单</h2></div>${orders.map(orderCard).join('')||empty("该客户暂无订单")}<div class="detail-bar">${btn('编辑',`edit:customer:${c.id}`,'primary secondary')}${btn('删除',`delete:customer:${c.id}`,'primary danger')}</div></div>`;}

function settingsView(){const s=settings();return `${header('提成设置','commission')}<div class="body"><form id="settings-form">${chipField('提成模式','mode',s.mode,['custom','fixed'],{custom:'自定义',fixed:'固定'})}<div data-mode-panel="fixed" ${s.mode==='fixed'?'':'hidden'}><div class="field"><label>统一比例（%）</label><input name="fixedRate" type="number" value="${h(s.fixedRate)}"></div></div><div data-mode-panel="custom" ${s.mode==='custom'?'':'hidden'}><div class="section"><h2>自定义课程比例</h2>${btn('＋ 添加课程','show-course-add','link')}</div>${state.courseAdd?`<div class="card">${field('课程名称','newCourseName','','text','如：瑜伽课')}${field('默认比例','newCourseRate',0,'number')}${field('默认价格','newCoursePrice',0,'number')}${btn('添加课程','save-course','primary')}</div>`:''}<div class="card">${all('course').map(c=>`<div class="row"><span>${h(c.name)} ${btn('✕',`delete:course:${c.id}`,'link')}</span><input aria-label="${h(c.name)}比例" name="rate-${h(c.id)}" type="number" min="0" max="100" value="${h(c.rate)}">%</div>`).join('')}</div></div><div class="section"><h2>课程价格（新增订单默认费用）</h2></div><div class="card">${all('course').map(c=>`<div class="row"><span>${h(c.name)}</span><input aria-label="${h(c.name)}价格" name="price-${h(c.id)}" type="number" min="0" value="${h(c.price)}">元</div>`).join('')}</div><div class="section"><h2>其他设置</h2></div><div class="field"><label><input name="countDue" type="checkbox" ${s.countDue!==false?'checked':''}> 待付款订单计入提成统计</label><small>关闭后待付款订单仅展示明细、不计入提成总额</small></div><div class="card"><h3>提成试算器</h3>${field('报名费用（元）','trialFee',3600,'number')}${field('优惠分摊（元）','trialDiscount',0,'number')}${field('提成比例（%）','trialRate',s.fixedRate,'number')}<div id="trial-result">实际提成 ${money(commissionPreview({fee:3600,discount:0,rate:s.fixedRate}).amount)}</div></div><div class="card">${[['结算明细','go:settlements'],['招生官管理','go:coaches'],['门店管理','go:stores'],['导出数据备份','backup:export'],['导入数据备份','backup:import']].map(([t,a])=>`<div class="row" data-action="${a}">${t}<b>›</b></div>`).join('')}</div><div class="save-bar"><button class="primary" type="submit">保存设置</button></div></form></div>`;}

function settlements(){const allOrders=all('order'),items=allOrders.filter(o=>state.settlementFilter==='all'||(state.settlementFilter==='settled'?o.settled:!o.settled)),total=sum(allOrders,earned),settled=sum(allOrders.filter(o=>o.settled),earned),monthSettled=allOrders.filter(o=>o.settled&&(o.settledAt||o.time||'').slice(0,7)===todayMonth()),groups=groupCoaches().sort((a,b)=>b.earned-a.earned);return `${header('结算明细','commission')}<div class="body"><div class="card"><small>结算进度</small><h3>已结算 ${money(settled)} · 待结算 ${money(total-settled)}</h3><div class="settle-track"><i style="width:${total?settled/total*100:0}%"></i></div><small>已完成 ${total?Math.round(settled/total*100):0}%</small></div><div class="stats"><div class="stat"><strong>${money(settled)}</strong><small>已结算</small></div><div class="stat"><strong>${money(total-settled)}</strong><small>待结算</small></div><div class="stat"><strong>${money(sum(monthSettled,earned))}</strong><small>本月已结算 · ${monthSettled.length} 笔</small></div></div><div class="chips">${[['all','全部'],['pending','待结算'],['settled','已结算']].map(([v,t])=>`<button class="chip ${state.settlementFilter===v?'active':''}" data-action="settlement-filter:${v}">${t}</button>`).join('')}</div><div class="bar">${btn('一键全部结算','settle-all','primary')}${btn('导出明细','export:settlements','primary secondary')}</div>${btn('导出本月已结算','export:month-settled','primary secondary')}<div class="section"><h2>招生官结算进度</h2></div>${groups.map(g=>card(g.name,`${g.orders.length} 单 · 已结算 ${g.earned?Math.round(g.settled/g.earned*100):0}%`,money(g.earned),`coach-name:${encodeURIComponent(g.name)}`)).join('')||empty('暂无订单数据')}<div class="section"><h2>订单结算明细</h2></div>${items.map(o=>`<div class="list-card"><div class="avatar">${h(o.name?.[0]||'客')}</div><div class="item-main" data-action="order:${h(o.id)}"><strong>${h(o.name)}</strong><small>${h(o.courseLabel||o.course)} · ${h(o.time||'')}</small></div><div class="item-right">${money(earned(o))}<small>${btn(o.settled?'已结算':'待结算',`settle:${o.id}`,'chip')}</small></div></div>`).join('')||empty("暂无订单")}</div>`;}

function coachDetail(name){const g=groupCoaches().find(x=>x.name===name), c=all('coach').find(x=>x.name===name);return `${header('招生官业绩','coaches')}<div class="body"><div class="card"><div class="avatar">${h(name[0])}</div><h2>${h(name)}</h2><p>客户 ${new Set((g?.orders||[]).map(o=>o.name+'|'+o.phone)).size} · 订单 ${g?.orders.length||0}</p>${tag(c?.status||'合作教练')}</div><div class="stats"><div class="stat"><strong>${money(g?.earned||0)}</strong><small>总提成</small></div><div class="stat"><strong>${money(g?.settled||0)}</strong><small>已结算</small></div></div><div class="card"><h3>基本信息</h3><div class="row">联系电话 <b>${h(c?.phone||'未填写')}</b></div><div class="row">入职日期 <b>${h(c?.join||'—')}</b></div><div class="row">身份证 <b>${h(c?.idcard||'未填写')}</b></div></div><div class="card"><h3>收款信息</h3>${[['开户银行',c?.bankName],['银行卡号',c?.account],['持卡人',c?.holder],['支付宝',c?.alipay],['微信',c?.wechat]].map(([label,value])=>`<div class="row"><span>${label}</span><b>${h(value||'未填写')}</b></div>`).join('')}</div><div class="card"><h3>结算进度</h3><p>已结算 ${money(g?.settled||0)} · 待结算 ${money((g?.earned||0)-(g?.settled||0))}</p><small>已完成 ${g?.earned?Math.round(g.settled/g.earned*100):0}%</small></div><div class="section"><h2>名下订单</h2></div>${(g?.orders||[]).map(orderCard).join('')}<div class="detail-bar">${c?btn('编辑',`edit:coach:${c.id}`,'primary secondary')+btn('删除',`delete:coach:${c.id}`,'primary danger'):''}</div></div>`;}
function profile(){return `${header('个人中心','home')}<div class="body"><div class="card profile-card"><div class="avatar">管</div><h2>管理员</h2><small>门店管理员</small></div><div class="stats"><div class="stat"><strong>${all('order').length}</strong><small>订单总数</small></div><div class="stat"><strong>${all('customer').length}</strong><small>客户总数</small></div><div class="stat"><strong>${money(sum(all('order'),earned))}</strong><small>累计提成</small></div></div><div class="card">${[['提成设置','go:settings'],['门店管理','go:stores'],['导出数据备份','backup:export'],['导入数据备份','backup:import']].map(([t,a])=>`<div class="row" data-action="${a}">${t}<b>›</b></div>`).join('')}</div></div>`;}
function render(){
 if(!state.view.startsWith('form:')&&!state.view.startsWith('coach-name:'))history.replaceState(null,'','#'+encodeURIComponent(state.view));
 let body=''; const [type,arg,extra]=state.view.split(':');
 if(type==='home')body=home();else if(type==='orders')body=listView('order');else if(type==='customers')body=listView('customer');else if(type==='stores')body=listView('store');else if(type==='coaches')body=coaches();else if(type==='commission')body=commission();else if(type==='reports')body=reports();else if(type==='settings')body=settingsView();else if(type==='settlements')body=settlements();else if(type==='profile')body=profile();else if(type==='form')body=formView(arg,extra);else if(type==='order')body=byId('order',arg)?detailOrder(byId('order',arg)):empty("订单不存在");else if(type==='customer')body=byId('customer',arg)?detailCustomer(byId('customer',arg)):empty("客户不存在");else if(type==='coach-name')body=coachDetail(decodeURIComponent(arg));
 const main=Object.hasOwn(names,type);
 root.innerHTML=`<div class="phone"><div class="screen ${main?'':'sub'}">${state.error?`<div class="error">${h(state.error)}</div>`:''}${body}</div>${main?nav():''}${state.modal?`<div class="mask"><div class="sheet"><h2>${h(state.modal.title)}</h2><p>${h(state.modal.text)}</p>${state.modal.choicesActions?`<div class="action-list">${state.modal.choicesActions.map(([label,action])=>`<button data-action="${h(action)}">${h(label)} ›</button>`).join('')}</div>`:''}${state.modal.choices?`<div class="month-choices">${state.modal.choices.map(m=>`<button class="chip ${state.month===m?'active':''}" data-action="month:${h(m)}">${h(m==='all'?'全部时间':m.replace('-','年')+'月')}</button>`).join('')}</div>`:''}${state.modal.password?'<input class="search" id="modal-password" type="password" autocomplete="off" placeholder="请输入密码">':''}<div class="bar">${btn('取消','modal-cancel','primary secondary')}${state.modal.choices||state.modal.choicesActions?'':btn('确认','modal-confirm','primary')}</div></div></div>`:''}${state.toast?`<div class="toast">${h(state.toast)}</div>`:''}<input id="file-input" type="file" hidden></div>`;
}
function notice(text){state.toast=text;render();setTimeout(()=>{state.toast='';root.querySelector('.toast')?.remove();},2400)}
async function load(){const kinds=['order','customer','coach','store','course','settings'];const rows=await Promise.all(kinds.map(k=>db.list(k)));kinds.forEach((k,i)=>state.data[k]=rows[i]);if(!state.monthInitialized){const months=state.data.order.map(o=>(o.time||'').slice(0,7)).filter(Boolean).sort();state.month=months.at(-1)||todayMonth();state.monthInitialized=true;}const order=['私教课','团课','年卡','体验课'];state.data.course.sort((a,b)=>{const ai=order.indexOf(a.name),bi=order.indexOf(b.name);return (ai<0?99:ai)-(bi<0?99:bi);});}
async function perform(fn){if(state.busy)return;state.busy=true;try{await fn();state.error='';await load();render();}catch(e){state.error=e.message||'操作未完成';render();}finally{state.busy=false;}}
const numeric = ['fee','discount','actualFee','customRate','fixedAmount','secondCommission','rate','price','fixedRate','practiceCount','joinedCount'];
async function saveForm(form){const kind=form.dataset.kind,id=form.dataset.id, previous=id?byId(kind,id):null;const f=new FormData(form);const record={...(previous||{})};for(const [key,value] of f.entries())record[key]=numeric.includes(key)?(value===''&&key==='customRate'?null:Number(value)||0):String(value).trim();if(!record.name)throw new Error('请填写名称');if(kind==='order'&&!record.course)throw new Error('请填写课程类型');if(kind==='course'&&all('course').some(c=>c.name===record.name&&c.id!==id))throw new Error('该课程已存在');
 if(kind==='order'){for(const [countKey,logKey] of [['practiceCount','practiceLog'],['joinedCount','joinedLog']]){const last=form.querySelector(`[data-counter-last="${countKey}"]`)?.textContent?.replace(/^最近：/,'');record[logKey]=record[countKey]&&last?[last]:[];}if(!f.has('useCustomRate'))record.customRate=null;delete record.useCustomRate;if(!id)record.autoCustomer=true;for(const flag of ['hasBook','enrolled','examinerConfirmed'])record[flag]=f.has(flag);record.settled=f.has('settled');record.commissionType ||= 'rate';record.time ||= today();record.status ||= 'paid';record.courseLabel=({'私教课':'私教课 12节','团课':'团体课月卡','年卡':'年卡会员','体验课':'体验课'})[record.course]||record.course;record.actualFee=f.get('actualFee')===''?Math.max(0,(record.fee||0)-(record.discount||0)):record.actualFee;if(record.settled&&!record.settledAt)record.settledAt=nowStr();}
 if(kind==='customer'){record.tags=f.getAll('tag');delete record.tag;record.join ||= today();}
 if(id)await db.update(kind,record);else await db.create(kind,record);
 state.view=kind==='order'?'orders':kind==='customer'?'customers':kind==='coach'?'coaches':kind==='store'?'stores':'settings';state.search='';notice('已保存');}
function csvCell(value){const s=String(value??'');const safe=/^[=+\-@]/.test(s.trim())?"'"+s:s;return /[",\n]/.test(safe)?'"'+safe.replaceAll('"','""')+'"':safe;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportFile(which){const rows=which==='commission'?commissionOrders():all('order');if(which==='coach'){const header=['招生官','客户数','订单数','报名费用','实际提成','已结算','未结算','结算比例'];const data=groupCoaches().map(x=>[x.name,new Set(x.orders.map(o=>o.name+'|'+o.phone)).size,x.orders.length,sum(x.orders,o=>(+o.fee||0)-(+o.discount||0)),x.earned,x.settled,x.earned-x.settled,x.earned?Math.round(x.settled/x.earned*100)+'%':'0%']);return download('招生官业绩报表.csv','\uFEFF'+[header,...data].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');}if(which==='settlements'){const header=['客户','课程','提成比例','提成方式','提成金额','结算状态','时间'];const data=rows.map(o=>[o.name,o.course,o.commissionType==='fixed'?'固定':orderCommission(o,settings(),all('course')).rate+'%',o.commissionType==='fixed'?'固定金额':'按比例',orderCommission(o,settings(),all('course')).earned,o.settled?'已结算':'待结算',o.time]);return download('结算明细.csv','\uFEFF'+[header,...data].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');}if(which==='month-settled'){const rows=all('order').filter(o=>o.settled&&(o.settledAt||o.time||'').slice(0,7)===todayMonth());if(!rows.length){notice('本月还没有已结算订单');return;}const header=['客户','课程','归属招生官','提成金额','结算时间'],data=rows.map(o=>[o.name,o.courseLabel||o.course,o.owner||'未分配',chartCommission(o),o.settledAt||o.time]);return download('本月已结算_'+todayMonth()+'.csv','\uFEFF'+[header,...data].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');}if(which==='template')return download('订单导入模板.csv','\uFEFF姓名,电话,课程,级别,费用,优惠,状态,时间,归属招生官,提成比例\n','text/csv;charset=utf-8');
 if(which==='commission'){const columns=['序号','姓名','电话','时间','课程','门店','归属招生官','报名费用','优惠分摊','提成比例','提成方式','实际提成','结算状态'];const data=rows.map((o,i)=>[i+1,o.name,o.phone,o.time,o.courseLabel||o.course,o.store||'未分配门店',o.owner||'未分配',o.fee,o.discount||0,o.commissionType==='fixed'?'固定':orderCommission(o,settings(),all('course')).rate+'%',o.commissionType==='fixed'?'固定金额':'按比例',orderCommission(o,settings(),all('course')).earned,o.settled?'已结算':'待结算']);data.push(['','','','','','','','','报名费用合计',sum(rows,o=>Number(o.fee)||0)]);data.push(['','','','','','','','','实际提成合计',sum(rows,earned)]);return download('提成明细.csv','\uFEFF'+[columns,...data].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');}
 if(which==='document'){const body=rows.map((o,i)=>`<tr><td>${i+1}</td><td>${h(o.name)}</td><td>${h(o.phone)}</td><td>${h(o.time)}</td><td>${h(o.courseLabel||o.course)}</td><td>${h(o.commissionType==='fixed'?'固定':orderCommission(o,settings(),all('course')).rate+'%')}</td><td>${h(money(orderCommission(o,settings(),all('course')).earned))}</td><td>${o.settled?'已结算':'待结算'}</td></tr>`).join('');return download('提成报表.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>提成报表</title><style>body{font-family:sans-serif;padding:24px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:8px}</style><h1>提成报表</h1><table><tr><th>序号</th><th>姓名</th><th>电话</th><th>时间</th><th>课程</th><th>比例</th><th>实际提成</th><th>结算</th></tr>${body}</table></html>`,'text/html;charset=utf-8');}
 if(which==='table'){const headers=['序','姓名','课程名称','日期','实付金额','实到金额','订金支付时间','尾款支付时间','支付方式','招生老师','班次','联系电话','教材','刷题','报名','进群','考场','跟进人','备注'];const data=rows.map((o,i)=>[i+1,o.name,o.courseLabel||o.course,o.enrollDate||o.time,o.fee,o.actualFee??Math.max(0,(+o.fee||0)-(+o.discount||0)),o.depositDate,o.balanceDate,o.payMethod,o.recruiter||o.owner,o.classTime,o.phone,o.hasBook?'1':'0',o.practiceCount?'1':'0',o.enrolled?'1':'0',o.joinedCount?'1':'0',o.examinerConfirmed?'1':'0',o.followUp||o.owner,o.remark]);const xml='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="报名学员信息跟进表"><Table>'+[headers,...data].map(row=>'<Row>'+row.map(v=>`<Cell><Data ss:Type="String">${h(v)}</Data></Cell>`).join('')+'</Row>').join('')+'</Table></Worksheet></Workbook>';return download('报名学员信息跟进表.xls',xml,'application/vnd.ms-excel');}}

function parseLine(line){let a=[],v='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){a.push(v);v='';}else v+=c;}a.push(v);return a;}
async function importOrders(file){
 const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());
 if(lines.length<2)throw new Error('文件内容为空');
 const phones=new Set(all('order').map(o=>String(o.phone||'').trim()));const courses=new Map(all('course').map(c=>[c.name,c]));let skipped=0;const pending=[],newCourses=[];
 for(const line of lines.slice(1)){
  const cells=parseLine(line);const [rawName,rawPhone,rawCourse,level,fee,discount,status,time,owner,rate]=cells;const name=(rawName||'').trim(),phone=(rawPhone||'').trim(),course=(rawCourse||'').trim()||'私教课';
  if(cells.length<4||!name||!phone||phones.has(phone)){skipped++;continue;}phones.add(phone);
  const customRate=rate?Number(rate.replace('%',''))||null:null;
  if(!courses.has(course)){const payload={name:course,rate:customRate||12,price:Number(String(fee||'').replace(/[,\s]/g,''))||0};courses.set(course,payload);newCourses.push({id:crypto.randomUUID(),payload});}
  const payload={name,phone,course,courseLabel:course,level:(level||'初级').trim(),fee:Number(String(fee||'').replace(/[,\s]/g,''))||0,discount:Number(String(discount||'').replace(/[,\s]/g,''))||0,status:status?.includes('待')?'due':'paid',settled:!status?.includes('待'),time:(time||today()).trim(),owner:(owner||'').trim(),customRate};pending.push({id:crypto.randomUUID(),payload});
 }
 if(!pending.length)throw new Error('未识别到有效订单，请检查格式');
 await db.importBatch(pending,newCourses);
 const after=await db.list('order');const accepted=new Set(after.map(o=>o.id));const added=pending.filter(o=>accepted.has(o.id)).length;
 notice(`导入成功 ${added} 笔，跳过 ${skipped+pending.length-added} 行`);
}
async function updateSettings(form){const f=new FormData(form),existing=all('settings')[0];if(!existing)throw new Error('设置未初始化');const {id,revision,...old}=existing;const items=[{kind:'settings',id,revision,payload:{...old,mode:f.get('mode'),fixedRate:Number(f.get('fixedRate'))||0,countDue:f.has('countDue')}}];for(const c of all('course')){const {id,revision,...payload}=c;payload.rate=Number(f.get('rate-'+id))||0;payload.price=Number(f.get('price-'+id))||0;items.push({kind:'course',id,revision,payload});}await db.updateMany(items);state.view='commission';notice('提成与价格设置已保存');}

function ask(title,text,confirm,password=false){state.modal={title,text,confirm,password};render();}
async function onAction(action){const [verb,kind,id,extra]=action.split(':');if(verb!=='modal-confirm'&&verb!=='modal-cancel'&&verb!=='order-menu'&&state.modal?.choicesActions)state.modal=null;if(verb==='home-unsettled'){state.filters.settled='unsettled';state.view='orders';state.search='';render();return;}if(verb==='go'){state.view=kind;state.search='';render();return;}if(verb==='new'){state.view=`form:${kind}`;render();return;}if(verb==='edit'){state.view=`form:${kind}:${id}`;render();return;}if(verb==='order'||verb==='customer'){state.view=action;render();return;}if(verb==='coach-name'){state.view=action;render();return;}if(verb==='order-menu'){state.modal={title:'订单操作',text:'选择操作',choicesActions:[['编辑',`edit:order:${kind}`],['复制订单',`duplicate:${kind}`],['切换结算',`settle:${kind}`],['删除订单',`delete:order:${kind}`]]};render();return;}if(verb==='duplicate'){const o=byId('order',kind);if(!o)throw new Error('订单不存在');await perform(async()=>{const {id,revision,settledAt,...copy}=o;await db.create('order',{...copy,autoCustomer:false,settled:false,settledAt:'',time:today()});state.view='orders';notice('订单已复制');});return;}if(verb==='set-order-filter'||verb==='set-customer-filter'||verb==='set-commission-filter'){const target=verb==='set-order-filter'?state.filters:verb==='set-customer-filter'?state.customerFilters:state.commissionFilters;if(Object.hasOwn(target,kind))target[kind]=decodeURIComponent(id);render();return;}if(verb==='customer-filter'){state.customerFilterOpen=!state.customerFilterOpen;render();return;}if(verb==='reset-customer'){state.customerFilters={tag:'all',store:'all',owner:'all'};render();return;}if(verb==='commission-filter'){state.commissionFilterOpen=!state.commissionFilterOpen;render();return;}if(verb==='reset-commission'){state.commissionFilters={store:'all',owner:'all',course:'all',status:'all'};render();return;}if(verb==='settlement-filter'){state.settlementFilter=kind;render();return;}if(verb==='coach-filter'){state.coachFilter=kind;render();return;}if(verb==='show-course-add'){state.courseAdd=!state.courseAdd;render();return;}if(verb==='save-course'){const form=document.getElementById('settings-form');const f=new FormData(form),name=String(f.get('newCourseName')||'').trim();if(!name){notice('请填写课程名称');return;}if(all('course').some(c=>c.name===name)){notice('该课程已存在');return;}await perform(async()=>{await db.create('course',{name,rate:Number(f.get('newCourseRate'))||0,price:Number(f.get('newCoursePrice'))||0});state.courseAdd=false;notice('课程已添加');});return;}if(verb==='open-month'){const months=[...new Set([todayMonth(),...all('order').map(o=>(o.time||'').slice(0,7)).filter(Boolean)])].sort().reverse();state.modal={title:'选择统计时间',text:'按订单月份统计提成与明细',choices:['all',...months]};render();return;}if(verb==='month'){state.month=kind;state.modal=null;render();return;}if(verb==='toggle-filter'){state.filterOpen=!state.filterOpen;render();return;}if(verb==='reset-filters'){state.filters={status:'all',settled:'all',course:'all',store:'all',owner:'all'};state.sort='time';render();return;}if(verb==='toggle-batch'){state.batchMode=!state.batchMode;state.selected=[];render();return;}if(verb==='select-order'){state.selected=state.selected.includes(kind)?state.selected.filter(x=>x!==kind):state.selected.concat(kind);render();return;}if(verb==='batch'){const selectedRows=all('order').filter(x=>state.selected.includes(x.id));if(!selectedRows.length){notice('请先选择订单');return;}const rows=kind==='settle'?selectedRows.filter(x=>!x.settled):selectedRows;if(!rows.length){state.batchMode=false;state.selected=[];notice('已结算 0 笔订单');return;}ask(kind==='delete'?'批量删除':'批量结算',`确认操作 ${rows.length} 笔订单？`,async()=>{await db.batchOrders(kind,rows,nowStr());state.batchMode=false;state.selected=[];notice('操作完成');});return;}if(verb==='modal-cancel'){state.modal=null;render();return;}if(verb==='modal-confirm'){const fn=state.modal?.confirm;const password=document.getElementById('modal-password')?.value||'';state.modal=null;if(fn)await perform(()=>fn(password));return;}
 if(verb==='quick-course'){const o=byId('order',kind);if(!o)return;if(!all('course').length){notice('暂无课程，请先到提成设置添加课程');return;}state.modal={title:'更换课程 · '+o.name,text:'选择课程',choicesActions:all('course').map(c=>[`${c.name} · ${c.price?money(c.price):'未设价格'} · 提成 ${c.rate}%`,`choose-course:${o.id}:${encodeURIComponent(c.name)}`])};render();return;}if(verb==='choose-course'){const name=decodeURIComponent(id);await perform(async()=>{const o=byId('order',kind),old=all('course').find(c=>c.name===o?.course),course=all('course').find(c=>c.name===name);if(!o||!course)throw new Error('订单或课程不存在');const labels={'私教课':'私教课 12节','团课':'团体课月卡','年卡':'年卡会员','体验课':'体验课'},fee=old?.price&&course.price&&o.fee===old.price?course.price:o.fee;await db.update('order',{...o,course:name,courseLabel:labels[name]||name,fee,customRate:null});notice('已改为 '+(labels[name]||name));});return;}if(verb==='order-level'){await perform(async()=>{const o=byId('order',kind);if(!o)throw new Error('订单不存在');await db.update('order',{...o,level:id});notice('级别已更新');});return;}if(verb==='flag'||verb==='count'){await perform(async()=>{const o=byId('order',id);if(!o)throw new Error('订单不存在');const next=verb==='flag'?!o[kind]:Math.max(0,(Number(o[kind])||0)+Number(extra));const updated={...o,[kind]:next};if(verb==='count'){const logKey=kind==='practiceCount'?'practiceLog':'joinedLog';const logs=[...(o[logKey]||[])];if(Number(extra)>0)logs.push(nowStr());updated[logKey]=next?logs:[];}await db.update('order',updated);notice('跟进记录已更新');});return;}if(verb==='settle'){await perform(async()=>{const o=byId('order',kind);await db.update('order',{...o,settled:!o.settled,settledAt:o.settled?'':nowStr()});notice(o.settled?'已标记为待结算':'已标记为已结算');});return;}
 if(verb==='delete'){const row=byId(kind,id);if(!row)return;const msg=kind==='customer'?'删除后不可恢复，关联订单不受影响。':kind==='coach'?'删除后订单与客户的归属信息将清空。':kind==='course'?'历史订单与客户不受影响。':'删除后不可恢复。';ask('确认删除',msg,async()=>{await db.remove(kind,row);state.view=kind==='order'?'orders':kind==='customer'?'customers':kind==='coach'?'coaches':kind==='course'?'settings':'stores';notice('已删除');});return;}
 if(verb==='export'){exportFile(kind);notice('已导出');return;}
 if(verb==='import'&&kind==='orders'){const f=document.getElementById('file-input');f.accept='.csv,text/csv';f.onchange=()=>{if(f.files[0])perform(()=>importOrders(f.files[0]));};f.click();return;}
 if(verb==='backup'&&kind==='export'){ask('导出数据备份','可设置密码加密备份；留空则不加密。',async password=>{const records=['order','customer','coach','store','course','settings'].flatMap(k=>all(k).map(({id,revision,...payload})=>({kind:k,id,payload})));download('健身管家备份_'+today()+'.json',await encodeBackup(records,password),'application/json');notice('备份已导出');},true);return;}
 if(verb==='backup'&&kind==='import'){const f=document.getElementById('file-input');f.accept='.json,application/json';f.onchange=async()=>{if(!f.files[0])return;const text=await f.files[0].text();let env;try{env=JSON.parse(text);}catch{notice('备份文件无效');return;}const encrypted=env.encrypted===true||env.enc===true;ask('恢复数据备份','恢复将覆盖订单、客户、招生官、门店、课程和设置。',async password=>{const records=await decodeBackup(text,password);await db.restore(records);notice('备份已恢复');},encrypted);};f.click();return;}
 if(verb==='quick-settle'){await perform(async()=>{const pending=all('order').filter(x=>!x.settled);if(!pending.length){notice('没有待结算订单');return;}await db.batchOrders('settle',pending,nowStr());notice(`已结算 ${pending.length} 笔待结算订单`);});return;}if(verb==='settle-all'){ask('一键结算','确认将全部待结算订单标记为已结算？',async()=>{const pending=all('order').filter(x=>!x.settled);if(pending.length)await db.batchOrders('settle',pending,nowStr());notice('已结算');});return;}
 if(verb==='theme'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('gym-theme',dark?'dark':'light');return;}
}
let longPressTimer=null,ignoreLongPressClick=false;
root.addEventListener('pointerdown',event=>{if(state.view!=='orders'||state.batchMode)return;const card=event.target.closest('[data-action^="order:"]');if(!card)return;const id=card.dataset.action.slice(6);clearTimeout(longPressTimer);longPressTimer=setTimeout(()=>{longPressTimer=null;ignoreLongPressClick=true;state.batchMode=true;state.selected=[id];render();setTimeout(()=>{ignoreLongPressClick=false},800);},500);},{passive:true});
for(const eventName of ['pointerup','pointermove','pointercancel'])root.addEventListener(eventName,()=>{if(longPressTimer){clearTimeout(longPressTimer);longPressTimer=null;}},{passive:true});
root.addEventListener('click',event=>{if(ignoreLongPressClick){ignoreLongPressClick=false;event.preventDefault();return;}const counter=event.target.closest('[data-counter]');if(counter){const form=counter.form,key=counter.dataset.counter,input=form.elements[key],next=Math.max(0,(Number(input.value)||0)+Number(counter.dataset.delta));input.value=next;form.querySelector(`[data-counter-value="${key}"]`).textContent=next;const last=form.querySelector(`[data-counter-last="${key}"]`);if(Number(counter.dataset.delta)>0)last.textContent='最近：'+nowStr();else if(!next)last.textContent='';return;}const chip=event.target.closest('[data-chip]');if(chip){const group=chip.closest('.field');const input=group.querySelector('input[type=hidden]');input.value=chip.dataset.value;group.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x===chip));if(input.name==='mode'){root.querySelectorAll('[data-mode-panel]').forEach(x=>x.hidden=x.dataset.modePanel!==input.value);}input.dispatchEvent(new Event('input',{bubbles:true}));return;}const target=event.target.closest('[data-action]');if(target){event.preventDefault();onAction(target.dataset.action).catch(e=>{state.error=e.message;render();});}});
root.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='edit-form')perform(()=>saveForm(form));else if(form.id==='settings-form')perform(()=>updateSettings(form));});
root.addEventListener('input',event=>{if(event.target.form?.id==='settings-form' && event.target.name.startsWith('trial')){const f=new FormData(event.target.form);const p=commissionPreview({fee:f.get('trialFee'),discount:f.get('trialDiscount'),rate:f.get('trialRate')});const result=document.getElementById('trial-result');if(result)result.textContent=`正价 ${money(p.base)} · 分摊 ${money(p.discount)} · 实际提成 ${money(p.amount)}`;return;}if(event.target.id==='search'){state.search=event.target.value;const caret=event.target.selectionStart;render();const f=document.getElementById('search');f?.focus();f?.setSelectionRange(caret,caret);return;}if(event.target.closest('#edit-form')?.dataset.kind==='order'){const f=new FormData(event.target.form);const course=all('course').find(c=>c.name===f.get('course'));const rate=!f.has('useCustomRate')?(settings().mode==='fixed'?settings().fixedRate:course?.rate):f.get('customRate');const p=commissionPreview({fee:f.get('fee'),discount:f.get('discount'),rate,commissionType:f.get('commissionType'),fixedAmount:f.get('fixedAmount')});const form=event.target.form;const actual=form?.elements.actualFee;if(actual && ['fee','discount'].includes(event.target.name))actual.value=Math.max(0,(Number(f.get('fee'))||0)-(Number(f.get('discount'))||0));const rateBox=form?.querySelector('.rate-fields'),fixedBox=form?.querySelector('.fixed-fields');if(rateBox)rateBox.hidden=f.get('commissionType')==='fixed';if(fixedBox)fixedBox.hidden=f.get('commissionType')!=='fixed';const box=document.getElementById('preview');if(box)box.textContent=`预计实际提成 ${money(p.amount)} · 正价 ${money(p.base)} · 分摊 ${money(p.discount)}`;}});
document.documentElement.dataset.theme=localStorage.getItem('gym-theme')||'light';
load().then(render).catch(e=>{state.error=e.message||'数据加载失败';render();});

root.addEventListener('change',event=>{if(event.target.dataset.customerFilter){state.customerFilters[event.target.dataset.customerFilter]=event.target.value;render();}else if(event.target.dataset.commissionFilter){state.commissionFilters[event.target.dataset.commissionFilter]=event.target.value;render();}else if(event.target.dataset.cdField){const key=event.target.dataset.cdField,id=event.target.dataset.id,value=event.target.value;perform(async()=>{const c=byId('customer',id);if(!c)throw new Error('客户不存在');await db.update('customer',{...c,[key]:value.trim()});notice('客户信息已更新');});}else if(event.target.dataset.odField){const key=event.target.dataset.odField,id=event.target.dataset.id,value=event.target.value;perform(async()=>{const o=byId('order',id);if(!o)throw new Error('订单不存在');const numeric=['fee','discount','secondCommission'];await db.update('order',{...o,[key]:numeric.includes(key)?Number(value)||0:value.trim()});notice('订单已更新');});}else if(event.target.dataset.filter){state.filters[event.target.dataset.filter]=event.target.value;render();}else if(event.target.id==='order-sort'){state.sort=event.target.value;render();}else if(event.target.id==='month'){state.month=event.target.value;render();}else if(event.target.name==='useCustomRate'){const input=event.target.form.elements.customRate;input.disabled=!event.target.checked;input.dispatchEvent(new Event('input',{bubbles:true}));}else if(event.target.name==='course' && event.target.form?.dataset.kind==='order'){const price=all('course').find(c=>c.name===event.target.value)?.price;const fee=event.target.form.elements.fee;if(price!=null&&fee)fee.value=price;fee?.dispatchEvent(new Event('input',{bubbles:true}));}});

window.addEventListener('hashchange',()=>{state.view=routeFromHash();state.search='';render();});
